  IF EXISTS (SELECT 1 FROM public.biblioteca_vectores WHERE ingest_batch IN ('A03_CODIGO_NINEZ_01','A04_D35_2013_01','PILOTO_D284_2013_01')
             AND metadata->>'estado_v' = 'V5' AND revision_pendiente = false) THEN
