INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:99','mayalex_normativos','10_LEYES_REGLAMENTOS','Quien contravenga lo dispuesto en los artículos 97 y 98 de este Código, será sancionado de acuerdo a las reglas siguientes:

1. Multa de veinte (20) a treinta (30) salarios mínimos en su valor más alto, en la categoría que determine la Ley de Salario Mínimo, si es por primera vez; 2. Suspensión de su permiso de operaciones hasta por dos (2) semanas, si es por segunda vez; y, 3. Cancelación de su permiso de operaciones, si es por tercer vez.

Tales sanciones serán impuestas por la autoridad que haya expedido los permisos de operación.

El importe de las multas establecidas en este Artículo será enterado en la Tesorería de las Alcaldías Municipales, dentro de los cinco (5) días hábiles siguientes al de su notificación quedando obligado el(a) infractor(a) a presentar el recibo de pago a la autoridad que le impuso la sanción, dentro de los tres (3) días siguientes. La Municipalidad respectiva debí

de utilizar estos fondos en programas y proyectos destinados a la niñez.','99','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":101,"article_sha256":"aa52b961f97b427e0d89a1038333dc104440ff3935df519c7f9ed00c999346b7","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','99','4e47d1339d88e348aeab728c9bbde7a9c6b395c52aa2527aedb40a007112f07e','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:100','mayalex_normativos','10_LEYES_REGLAMENTOS','La Secretaría de Estado en los Despachos de Gobernación y Justicia, por medio de las gobernaciones políticas y de las corporaciones municipales, adoptará las medidas que sean necesarias para evitar y combatir la prostitución infantil.','100','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":102,"article_sha256":"53c10c994823dff3a27e9651fc559144b8b6dd63e6f9a004b203e72e65c86957","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','100','ff90fba49d01b68bafae25e33246502f89b75c8d338d13ff712a612a1ef4a768','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:100-A','mayalex_normativos','10_LEYES_REGLAMENTOS','El Estado, por medio del Instituto Hondureño de la Niñez y la Familia (IHNFA) y en coordinación con el Programa Nacional de Prevención, Rehabilitación y Reinserción de Personas en maras y pandillas, implementará planes y programas, las medidas y las acciones de prevención y atención integral de los niños y niñas simpatizantes, pertenecientes o integrantes de pandillas o maras, con enfoque garantista de derechos y a nivel comunitario o local.','100-A','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":103,"article_sha256":"9d5e0704db20c57425bbabc279633d88785d97c3a23fe5f82189abd365f9804d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','100-A','55714af09300e5a9129bdd05620525d890be46737816b688f9a9832ee050e80a','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:101','mayalex_normativos','10_LEYES_REGLAMENTOS','Los niños sólo podrán salir del país si van acompañados de su padre, de su madre o de su representante legal o, en defecto de éstos, de la persona que cuente con la respectiva autorización escrita.

Si la patria potestad la ejercen ambos padres, se requerirá la autorización escrita del otro si sólo uno acompañara al niño durante el viaje.

Las correspondientes firmas deberán ser autenticadas por Notario.','101','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":104,"article_sha256":"9a9f0c80509f8a46577fa069afcf18e73a053738f30510454feb3d77f48b14be","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','101','80d0559215d80a57aaeb026733c27b6fe928ab359ca996bfea8c4ce13632e285','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:102','mayalex_normativos','10_LEYES_REGLAMENTOS','El padre o madre que haya sido suspendido(a) o privado del ejercicio de la patria potestad, solo podrá trasladar a sus hijos menores de dieciocho (18) años, dentro o fuera del país, previa autorización escrita de quien la deba otorgar.

En caso de no portar la referida autorización, el(la) Juez Competente, a petición de parte interesada, ordenará a las autoridades de policía se le requiera para que dentro de las veinticuatro (24) horas siguientes proceda a entregarlo(a).','102','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":105,"article_sha256":"235bf60aef4ab4920a4fb94506b7cc4811d55282a6824236c3cd947f3365f95f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','102','993c5257592ef1f6900b4cd8f90c2f9e0ca470eff37ce370a6b3b77df484e1b6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:102-A','mayalex_normativos','10_LEYES_REGLAMENTOS','Si la patria potestad es ejercida por ambos padres y si uno de ellos se negare a autorizar la salida del país de su hijo(a), podrá el(la) padre o madre, interesado(a) concurrir al(la) Juez(a) competente a fin de que éste(a) le autorice.

Lo establecido en este Artículo solamente será aplicable en los casos siguientes:

1) Que sea necesaria su atención médica en el extranjero; 2) Estudios, siempre que no haya oportunidades de estudio equivalentes en el país; y, 3) Viajes por motivos académicos, deportivos o artísticos, siempre que sean a cargo de las autoridades educativas, religiosas o federativas correspondientes o análogas debidamente calificadas.

En la autorización judicial deberá establecerse el destino y duración del viaje, así como el nombre de la persona a cuyo cargo estará el niño(a), en el caso de que no viaje con uno(a) de los padres.

Lo dispuesto en este Artículo será aplicable al tutor(a) o al Instituto Hondureño de la Niñez y la Familia (IHNFA), en su caso; y también se aplicará en el caso que sea imposible ubicar al padre o madre del niño o niña.','102-A','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":106,"article_sha256":"9c34537f031a8c4291182e057a565eece8eac397e087b87bff6ce0d5037b9e42","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','102-A','0e7fa30a04d5cd5e960a46ca6e54c841f443d27c5f524555352ae87d39c50a6e','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:103','mayalex_normativos','10_LEYES_REGLAMENTOS','Los jueces de la niñez tendrán derecho a impedir la salida de un niño del país cuando quien pretenda llevárselo se halle en el ejercicio de la patria potestad pero no le esté dando cumplimiento a sus obligaciones legales o a las que le haya impuesto la autoridad competente. Adoptada la resolución, la pondrán sin tardanza en conocimiento de las autoridades de migración para los efectos consiguientes.

Si pese a la orden judicial el niño sale del país, se seguirá juicio criminal contra el culpable y se adoptarán las medidas necesarias para el rescate de aquél.','103','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":107,"article_sha256":"d32bb876a4aaad575baa61683f6a15337344722fabae63c9383e73aae5b6073f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','103','c9740cf466409ddec69825189727f597387d341bd64d2846eb1fbb41f1393f3f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:104','mayalex_normativos','10_LEYES_REGLAMENTOS','La solicitud de autorización o impedimento de salida del país, deberá contener:

a) El nombre y apellidos del niño o niña; b) . Los nombres y demás generales de los padres, o representante legal; c) El nombre completo y generales de la persona que acompañará al niño o niña; y, d) La relación de los hechos en que se funda la solicitud, con la cual se acompañará la certificación de partida de nacimiento y demás pruebas pertinentes.','104','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":108,"article_sha256":"d160643ce293bc97d31d6cb55106de9199d0fd417da69154f96895c1262d64dd","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','104','98283be6a59eb7cd64e2c6f88a2d0f3f00112fcee454364b4855b224f8e56517','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:104-A','mayalex_normativos','10_LEYES_REGLAMENTOS','Presentada la solicitud, el(la) Juez(a) citará en legal y debida forma a la parte contraria, para que dentro del término de tres (3) días siguientes a la fecha de la citación, comparezca a una audiencia en la que se conocerá el asunto breve y sumariamente, debiéndose dictar sentencia en la misma o a más tardar al día siguiente. Contra dicha resolución cabrán los recursos de reposición y apelación subsidiaria.

La oposición deberá resolverse en la misma audiencia.

Las partes deberán presentarse a la audiencia, con las pruebas en que sustenten sus argumentaciones.

La Cédula de Citación deberá ser acompañada de la copia de la solicitud respectiva.

En caso de no cumplimentarse la citación por no ubicarse a la persona citada, el(la) Juez(a) resolverá de conformidad'' con las pruebas que acompañen la solicitud, en el término de tres (3) días, sin la realización de la audiencia.','104-A','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":109,"article_sha256":"f5ebf524a33f8f039472fd29b46b8016c98a159a3e3e4e5ce2a36e9ac0f2a0b9","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','104-A','00aae460146a051fbe465b96de0184fd14ad56cf047e2beb91dac6dee22f8a20','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:105','mayalex_normativos','10_LEYES_REGLAMENTOS','Quien tenga a su cuidado un niño o una niña, estando fuera del país por cualquier causa y no ejerza la Patria Potestad sobre él o ella, necesitará autorización de quien la ejerza o en su defecto del(la) Juez de Letras de la Niñez o quien haga sus veces. Igualmente podrá acudir al(la) Juez(a) para que le autorice la salida en el caso de que quien ejerza la Patria Potestad le niegue la respectiva autorización.

Cualquier autoridad o persona particular que tenga conocimiento de que se trata de sacar un(a) niño(a) en violación de lo contenido en el párrafo precedente está en la obligación de poner en conocimiento de la autoridad correspondiente tal situación de acuerdo a las reglas siguientes:

1) Ante el(la) Juez de Letras de la Niñez o quien haga sus veces en el caso de que no se haya llegado al control migratorio; y,

2) Ante la autoridad migratoria cuando se detecte la supuesta intención de sacar al niño(a) del país, en el control migratorio.

En el caso del numeral 2) precedente la autoridad competente deberá poner en conocimiento, del(la) Juez de la Niñez o quien haga sus veces y del Ministerio Público tal situación, para los efectos legales correspondientes, de conformidad al Convenio de La Haya relativo a Cooperación Internacional en Materia de Sustracción de Menores.

En el caso que ya se haya producido la sustracción internacional, se deberá poner en conocimiento ante el Instituto Hondureño de la Niñez y la Familia (IHNFA) o la institución en la que se delegue.','105','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":110,"article_sha256":"fe57140c82d29efe47cdc519e17680e5476c1242b5767f7e9c41013f86c80c2c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','105','a9c1974c4a398fe5e5bf12c47f7ec7a7d5ca4733e9df0d2b888805cb36a1867a','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:106','mayalex_normativos','10_LEYES_REGLAMENTOS','Las autoridades de migración no permitirán la salida del territorio nacional de un menor respecto del cual no se haya cumplido los requisitos señalados en los artículos precedentes. Tampoco permitirán que una autorización se utilice más de una vez.','106','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":111,"article_sha256":"d6294aecb689c03f1a0e8156ead953e0995b65ce733e781f25d805af00e6c498","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','106','a66daa55879689cb66ca85a1205f0ae94e5c770e4c904e66acebf148e5df7d54','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:107','mayalex_normativos','10_LEYES_REGLAMENTOS','Para todos los efectos legales, niño discapacitado es aquel que presenta alguna carencia o limitación, temporal o definitiva, de carácter físico, sensorial o mental que le dificulte o imposibilite para la realización autónoma de sus actividades, cotidianas y para su desarrollo e integración social.','107','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":112,"article_sha256":"99e5c44612d8f76d937aa9ff48c83e36d7eecde8d31e71c6f769277247ff5c8c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','107','1fea06571b3d63229627716bcbb219c01a9624742ce28be5a99758df71337d3f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:108','mayalex_normativos','10_LEYES_REGLAMENTOS','Los niños discapacitados tienen derecho a gozar de una vida plena, así como de cuidados y atenciones especializadas y, de ser posible, individualizadas, para asegurarles su dignidad y permitirles bastarse a sí mismos y facilitar su participación activa en la comunidad.

La atención de los niños discapacitados le corresponde prioritariamente a la familia y complementaria y subsidiariamente al Estado, en los términos de este Código.

En tal orden, deberán hacer lo necesario para garantizarles el acceso a la educación, a la capacitación para el trabajo, al sano esparcimiento y a las demás actividades que hagan factible su rehabilitación y su pleno desarrollo individual.','108','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":113,"article_sha256":"aea8dbc3c437b20282960f17e9ac3f096078abf13afcc15f1e463777b7bc9aac","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','108','e7da8a8e2fb5199640d6ace53d3d1e9bc10b25665e4adb14ed31fc8181b6f3a3','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:109','mayalex_normativos','10_LEYES_REGLAMENTOS','Es deber del Estado promover, desarrollar y coordinar programas de prevención, tratamiento y rehabilitación para los niños discapacitados. Con tal fin, creará y fomentará servicios especializados que atiendan, evalúen periódicamente y aseguren el acceso efectivo de aquellos a la educación, a los servicios de salud y de rehabilitación, a la capacitación para el trabajo, al esparcimiento y a los deportes.

El padre, la madre o los representantes legales de un niño discapacitado tienen la obligación de someter a éste a los tratamientos adecuados y de integrarse activamente a los procesos de rehabilitación.

La renuencia u oposición injustificada de los padres o representantes legales a cumplir las obligaciones señaladas en este artículo dará derecho al Instituto Hondureño de la Niñez y la Familia a adoptar las medidas de protección que estime apropiadas.','109','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":114,"article_sha256":"691b31caa4f4b6c0178db2cf404a4e465b4bbb5949719e1763cc568a3e96cfd3","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','109','60a64d4174ffd5ef170e0af7caab39ba5224efb3531d1ef15b071b78c7edbf0e','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:110','mayalex_normativos','10_LEYES_REGLAMENTOS','Es deber de toda persona que tenga conocimiento de la existencia de un niño discapacitado ponerlo en conocimiento del Instituto Hondureño de la Niñez y la Familia, del Ministerio Público o de los Juzgados de la Niñez u otros que hagan sus veces, para que pueda recibir el tratamiento adecuado.

Los maestros de educación preescolar, primaria y media que detecten cualquier dificultad para el aprendizaje que presenten los niños discapacitados, deberán dar cuenta del hecho a sus superiores jerárquicos, así como a los correspondientes padres o representantes legales para que puedan adoptar las medidas correctivas que las circunstancias exijan.','110','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":115,"article_sha256":"e330c4c3c352d2b08f447633efba63f3447787d6c245aed9bef8ce245d878a94","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','110','11a44fbdb49e60805900f984c11737455e857159f83585f8699bdcccbbc52bf7','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:111','mayalex_normativos','10_LEYES_REGLAMENTOS','Para la debida protección y rehabilitación de los niños a que esta Sección se refiere y en procura de garantizar su igualdad con todos los demás, el Instituto Hondureño de la Niñez y la Familia:

1) Vigilará el cumplimiento, por parte de la familia, de las obligaciones que le corresponden con miras a lograr la rehabilitación del niño y que lo haga con pleno respeto de su dignidad. Colaborará con ella, además, para alcanzar dichos objetivos; y, 2) Promover, con la participación de las Secretarías de Estado en los Despachos de Educación y Salud, programas dirigidos tanto a la prevención de las deficiencias mediante campañas educativas y profilácticas, como a la rehabilitación de los discapacitados, apoyando la educación especial, la integración de aquellos a la educación regular, creando talleres y consejos para su capacitación, haciendo posible su recreación y su participación en olimpiadas especiales y demás medios encaminados a la rehabilitación integral de los discapacitados.','111','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":116,"article_sha256":"7958c49e2d0b9508803097172590957b3597e32a8b6a8aa88d133432985342ad","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','111','2b14fca84e37fe68532e130678bd2d1e8db30fc04cdcc87f5730191d5a1a24f2','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:112','mayalex_normativos','10_LEYES_REGLAMENTOS','Los consejos a que se refiere el artículo anterior tendrán las funciones siguientes:

a) Proponer proyectos dirigidos a la prevención, detección, promoción, tratamiento, rehabilitación e investigación en el campo de los niños discapacitados.

b) Formular recomendaciones al Instituto Hondureño de la Niñez y la Familia para la elaboración y aprobación de programas orientados a atender las necesidades de los niños discapacitados.

c) Colaborar con la Secretaría de Salud en la prevención y detección de deficiencias mentales, físicas y sensoriales, con especial énfasis en la asistencia prenatal y de la primera infancia.

ch) Promover la organización de aulas públicas y privadas para la educación especial de los niños discapacitados, al igual que su integración al sistema educativo regular y a los programas del Instituto Nacional de Formación Profesional.

d) Fomentar el desarrollo de políticas de subsidio familiar dirigidas a proteger en forma especial a los niños discapacitados y a dar orientación y apoyo a la familia de la cual dependen.

e) Promover la formación de personal profesional, técnico y auxiliar de las actividades y disciplinas cuyo objeto sea la rehabilitación de los niños discapacitados.

f) Promover, a través de los sectores públicos y privados, investigaciones científicas dirigidas a buscar el mayor conocimiento de esta problemática; y, g) Promover una mayor divulgación de las deficiencias que se observen en los niños con miras a crear una conciencia colectiva que facilite la participación de la comunidad en la prevención y solución de sus problemas.','112','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":117,"article_sha256":"0a58b59d2c66a0368435906c688c0592113da547760e05b6393276a7793b2795","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','112','423390508f0336a05cf2c4913bff0f76d3db277165943963367c330243e78ec3','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:113','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Secretarías de Estado en los ramos de Salud, Educación e Interior y Población conjuntamente con el Instituto Hondureño de la Niñez y la Familia (IHNFA), la Dirección General de las Personas con Discapacidad (DIGEDEPDI) y otras instituciones públicas, privadas y asociaciones civiles vinculadas, formularán, coordinarán y desarrollarán políticas, programas, planes y actividades encaminadas a garantizar los derechos de los niños y niñas con discapacidad.

Cuando las personas de quienes el niño(a) dependa, incumplan o vulneren sus derechos, o se opongan a que reciban atención, serán denunciados ante el Instituto Hondureño de la Niñez y la Familia (IHNFA), Policía, Ministerio Público, y en su defecto ante los Juzgados de Paz, Comisionados Municipales de Derechos Humanos, Defensorías de la Niñez, Mujer, por cualquier persona o institución que tenga conocimiento de dicha situación, para asegurar las medidas urgentes de protección.','113','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":118,"article_sha256":"68835507eab805aabdc6c0238c90135a2d067c6e0d63299c577688bca3651d50","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','113','9223290234faf54d6eefed707861ca3a780b8e858fc6026a368454c0d6f5947a','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:114','mayalex_normativos','10_LEYES_REGLAMENTOS','Es deber del Estado formular políticas y elaborar, promover y ejecutar programas tendentes a la gradual abolición del trabajo de los niños.

Creará, asimismo, programas de apoyo a las familias en las que existan niños en situación de riesgo.','114','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":119,"article_sha256":"fb6b6f78b78ef24b9c17677b45ea69ed42850fdcda53f67c5872dac5a73ee9a5","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','114','6a2a364f62858d43d0fb2b1e75e99260ff1c880024858e1a178c92523f7e42a1','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:115','mayalex_normativos','10_LEYES_REGLAMENTOS','El trabajo de los niños deberá ser adecuado a su edad, condiciones físicas y desarrollo intelectual y moral.

La Secretaría de Estado en los Despachos de Trabajo y Previsión Social evitará la explotación económica de los niños y velará porque no realicen trabajos peligrosos o que entorpezcan su educación o afecten su salud o su desarrollo físico o mental.

Los niños que ingresen a la fuerza laboral tendrán derecho al salario, prestaciones sociales y demás garantías que la ley y los contratos individuales o colectivos le conceden a los trabajadores mayores de dieciocho (18) años y a los especiales que por razón de su edad y desarrollo le son reconocidos por el Código del Trabajo y por el presente.

El salario del niño trabajador será proporcional a las horas trabajadas.','115','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":120,"article_sha256":"9cdccadfa4ad236b63735cff60feee65d5794c8d19e3e52b3cfac87cb445e457","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','115','d430d254d4b1dd1602a73f0de913a14cfd7e3642b28ed461c991ece229451070','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:116','mayalex_normativos','10_LEYES_REGLAMENTOS','Las niñas trabajadoras gozarán de protección especial en caso de gravidez y lactancia materna.','116','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":121,"article_sha256":"689029edc76564d41ef5ec6bde3a4152ac01490453c788e8bceb41b1759f07e5","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','116','c9b2a071e947102a003ed1ceb7c93e22a1854f3ce873370d56353a7def757724','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:117','mayalex_normativos','10_LEYES_REGLAMENTOS','El trabajo de los niños, además de retributivo deberá ser formativo y orientador.','117','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":122,"article_sha256":"347ff8e719c41a870e5e821cf751b7623bf5bdc8d3858d0acbb8b206820a0005","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','117','1b8dc48ead71929bfac6e43786183249ec91fccd3f4626a38b43485e133e9250','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:118','mayalex_normativos','10_LEYES_REGLAMENTOS','El trabajo de los niños no deberá ser limitante para su superación.

Con tal fin, deberá existir una estrecha coordinación entre las Secretarías de Estado en los Despachos de Trabajo y Seguridad Social y Educación, a fin de lograr los objetivos anteriores.','118','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":123,"article_sha256":"fe17eada046cd651d31d2a5cee68765d3edd8f9f9c2213336757cc655bfad69b","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','118','28751263650d7407ce601ad9003c0db6bafa0c951f16aa06c0bad5128e2d92a7','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:119','mayalex_normativos','10_LEYES_REGLAMENTOS','El empleo de niños en cualquier actividad retribuida estará sujeto a lo prescrito por el artículo 128 numeral 7 de la Constitución de la República y requerirá de la autorización previa de la Secretaría de Estado en los Despachos de Trabajo y Seguridad Social a solicitud de los padres, de los hermanos o del representante legal. Igual autorización requerirán los niños que se propongan realizar trabajos independientes, esto es, aquellos en que no medie una remuneración ni un contrato o relación de trabajo.

Para extender tal autorización dicha Secretaría de Estado deberá realizar un estudio socio-económico y del estado físico y mental de los niños de que se trate.

La autorización se concederá cuando, a juicio de la mencionada Secretaría de Estado, el niño no sufrirá perjuicio aparente, físico, moral o educativo por el ejercicio de la actividad de que se trate.

Concedida la autorización, el niño podrá recibir directamente el salario y, llegado el caso, a ejercitar, con el auxilio de un apoderado legal, las acciones pertinentes.','119','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":124,"article_sha256":"743f85b253b2da9d9e5ddd0fdab73d19618be7c05f281442156821b5080e95d0","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','119','e5a5858597ce16d1ab6cce06eda8e65635e1bd64e2ea3a5afed3f96a24f5e7ea','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:120','mayalex_normativos','10_LEYES_REGLAMENTOS','Las autorizaciones para trabajar se concederán a título individual y deberán limitar la duración de las horas de trabajo y establecer las condiciones en que se prestarán los servicios.

En ningún caso se autorizará para trabajar a un niño menor de catorce (14) años.','120','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":125,"article_sha256":"d4d806562f7921e1cbd0ba389ec0af6f4d20b36a6e9bf88aa25bf02062d8669e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','120','d6bbed5c9ed8d21cbe6bfdb272613942b6450a760fc5d8c93732a4f71089c5be','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:121','mayalex_normativos','10_LEYES_REGLAMENTOS','Se considerará trabajo educativo la actividad laboral en la que las exigencias pedagógicas prevalezcan sobre el aspecto productivo. La remuneración que se pague al estudiante no desvirtuará el carácter educativo de la labor.

Los centros de trabajo que utilicen a estudiantes que realizan su práctica educativa social no podrán destinar al educando a labores distintas de aquellas a que está orientada la práctica.

No obstante, la temporalidad del trabajo educativo social, al estudiante deberá ofrecérsele condiciones adecuadas para la realización de su trabajo, incluso en lo relacionado con la retribución de sus servicios.','121','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":126,"article_sha256":"20570d30951eff0b4cbc30d88e7753d185bb84219bc706b2a25ed5f7349759f6","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','121','99afa08efeb16b1d9af19f96d7c97257ba772ab948f6bc8a37407b0e6a5c9441','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:122','mayalex_normativos','10_LEYES_REGLAMENTOS','Los niños no podrán desempeñar labores insalubres o peligrosas aun cuando sean realizadas como parte de un curso o programa educativo o formativo.

La insalubridad o peligrosidad se determinará tomando como base lo dispuesto en este Código, en el Código de Trabajo y en los reglamentos que existan sobre la materia.

Tomando en cuenta lo anterior, los niños no podrán realizar labores que:

a) Impliquen permanecer en una posición estática prolongada o que deban prestarse en andamios cuya altura exceda de tres (3) metros.

b) Tengan que ver con sustancias tóxicas o nocivas para la salud.

c) Expongan al tráfico vehicular.

ch) Expongan a temperaturas anormales o deban realizarse en ambientes contaminados o con insuficiente ventilación.

d) Deban realizarse en túneles o subterráneos de minería o en sitios en los que confluyan agentes nocivos tales como contaminantes, desequilibrios térmicos, deficiencias de oxígeno a consecuencia de la oxidación o la gasificación.

e) Los expongan a ruidos que excedan ochenta (80) decibeles.

f) Impliquen la manipulación de sustancias radioactivas, pinturas luminiscentes, rayos X o impliquen la exposición a radiaciones ultravioletas o infrarrojas y a emisiones de radiofrecuencia.

g) Impliquen exposición a corrientes eléctricas de alto voltaje.

h) Exijan la inmersión en el mar.

i) Tengan que ver con basureros o con cualquier otro tipo de actividades en las que se generen agentes biológicos patógenos.

j) Impliquen el manejo de sustancias explosivas, inflamables o cáusticas.

k) Sean propios de fogoneros en los buques, ferrocarriles u otros bienes o vehículos semejantes. l) Sean propios de la pintura industrial y extrañen el empleo de albayalde o cerusa, de sulfato de plomo o de cualquier otro producto que contenga dichos elementos. ll) Se relacionen con máquinas esmeriladoras, de afilado de herramientas, muelas abrasivas de alta velocidad o con ocupaciones similares.

m) Se relacionen con altos hornos, hornos de fundición de metales, fábrica de acero, talleres de laminación, trabajo de forja o en prensas pesadas.

n) Involucren manipular cargas pesadas.

ñ) Se relacionen con cambios de correas de transmisión, de aceite o engrase u otros trabajos próximos a transmisiones pesadas o de alta velocidad.

o) Se relacionen con cortadoras, laminadoras, tornos, fresadoras, troqueladoras y otras máquinas particularmente peligrosas.

p) Tengan relación con el vidrio o con el pulido y esmerilado en seco de vidrio o con operaciones de limpieza por chorro de arena o con locales de vidriado y grabado.

q) Impliquen soldadura de cualquier clase, cortes con oxígeno en tanques o lugares confinados o en andamios o molduras precalentadas. r) Deban realizarse en lugares en los que se presentan altas temperaturas o humedad constante.

s) Se realizan en ambientes en los que se desprenden vapores o polvos tóxicos o que se relacionen con la producción de cemento. t) Se realicen en la agricultura o en la agroindustria que impliquen alto riesgo para la salud.

u) Expongan a un notorio riesgo de insolación; y, v) Señalen en forma específica los reglamentos que sobre la materia emita la Secretaría de Estado en los Despachos de Trabajo y Seguridad Social.

La mencionada Secretaría de Estado podrá autorizar a niños mayores de dieciséis (16) años y menores de dieciocho (18) para que puedan desempeñar alguna de las labores señaladas en este artículo si se prueba a satisfacción de la misma que han concluido estudios técnicos en el Instituto Nacional de Formación Profesional o en un instituto técnico especializado dependiente de la Secretaría de Estado en el Despacho de Educación. Aquella entidad, en todo caso, verificará que los cargos puedan ser desempeñados sin peligro para la salud o la seguridad del niño.','122','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":127,"article_sha256":"c699798e003c9dbc3e3b5e941115b1c8984e9102fde0d827eba49799c9e28ae5","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','122','756a543da8bee3734c3cdfc64ad05cddabe92ff88ee7412e064ea75a6fd39c6f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:123','mayalex_normativos','10_LEYES_REGLAMENTOS','Queda prohibido a los niños menores de dieciocho (18) años todo trabajo que afecte su moralidad. En especial les está prohibido el trabajo en casas de lenocinio y demás lugares de diversión donde se consuman bebidas alcohólicas.

Es también prohibida su contratación para la reproducción de escenas pornográficas, muertes violentas, apología del delito u otras labores semejantes.','123','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":128,"article_sha256":"bc1f63a2972e97cdaf44c9af75ca7a5fe494aefa12211f97c19eb9002b35ae3b","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','123','7bd5858856eb3b1b5b1cf56d5c97944e127918c40e0d4e5614ad43c9fbca68b8','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:124','mayalex_normativos','10_LEYES_REGLAMENTOS','Las personas que tengan conocimiento de la participación de niños en trabajos prohibidos en esta sección, deberá informar a la Secretaría de Trabajo y Seguridad Social para la aplicación de los correctivos y sanciones a que haya lugar.','124','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":129,"article_sha256":"b86251a78d0ceda9f7e19343ce0f2f41702cc5d40569ca6c9d8c9b56aec1a525","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','124','07a123aee354cab3b8791c5efc7e88662d42d09330573c62b850ad32dc0dce4f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:125','mayalex_normativos','10_LEYES_REGLAMENTOS','La duración máxima de la jornada de trabajo de los niños estará sujeta a las reglas siguientes:

a) El mayor de catorce (14) años y menor de dieciséis (16) sólo podrá realizar trabajos en jornadas que no excedan de cuatro (4) horas diarias.

b) El mayor de dieciséis (16) años y menor de dieciocho (18) sólo podrá trabajar en jornadas que no excedan de seis (6) horas diarias; y, c) Queda prohibido el trabajo nocturno para los niños trabajadores. No obstante, los mayores de dieciséis (16) años y menores de dieciocho (18) podrán ser autorizados para trabajar hasta las ocho (8) de la noche siempre que con ello no se afecte su asistencia regular a un centro docente ni se cause perjuicio a su salud física y moral.','125','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":130,"article_sha256":"25a7856e60598f34c46cf99338cb898516a4a24d6eb63d207455f081e5b0e466","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','125','f32500bbcebc850bb303ac118c04ba4e309597c99e24bbd50189fc3036236bb6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:126','mayalex_normativos','10_LEYES_REGLAMENTOS','Todo empleador que ocupe los servicios de niños llevará un registro en el que hará constar:

a) El nombre, apellidos, edad, dirección y domicilio del niño.

b) El nombre, apellidos, dirección y domicilio de sus padres o representantes legales.

c) La clase de trabajo que realiza, las horas diarias y semanales que trabaja, con indicación de los períodos de descanso.

ch) La forma y monto de la retribución o salario; y, d) La fecha de ingreso al trabajo.

A dicho registro se agregarán la constancia, extendida por las autoridades competentes, de que el niño está cumpliendo o ha cumplido sus obligaciones escolares, así como la autorización escrita de sus padres o representantes legales, con el visto bueno de la Secretaría de Trabajo y Seguridad Social.','126','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":131,"article_sha256":"f5f6e5f21b5fccc25f81ec76f63ce7e061a37e7eaa5df6aba01d0f14f8429af2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','126','5aa51f922c95baede7f55a2753fe41bea58769283c48cb59365b2fb0fd8f6195','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:127','mayalex_normativos','10_LEYES_REGLAMENTOS','La aptitud para el trabajo de los niños trabajadores será objeto de control médico cada seis (6) meses, o antes si las circunstancias lo exigen.','127','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":132,"article_sha256":"5bfd4697ad5d188fcd3bcec45cb5fb533a15fba82eae1057e01b3626fe3f4d2f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','127','668e01e057fa21b28fcdc0bdff887ead178f6bd7452989e4d372be9ce41899d4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:128','mayalex_normativos','10_LEYES_REGLAMENTOS','La Secretaría de Estado en los Despachos de Trabajo y Seguridad Social inspeccionará regular y periódicamente a las empresas, centros y lugares de trabajo y casas de habitación y en este último caso, previa autorización judicial cuando éste sea su centro de trabajo, para verificar si tienen a su servicio niños y niñas y si están cumpliendo las normas que los protegen.

Quién transgreda dichas normas será sancionado(a) con multa de cinco (5) a quince (15) salarios mínimos en su valor más alto. La reincidencia será sancionada con el doble de la multa anterior.

Cuando se haya puesto en peligro la vida de un niño o niña o se haya atentado contra su dignidad, integridad física, psíquica o intelectual, además de la multa prevista se le aplicarán las sanciones civiles y penales a que haya lugar.','128','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":133,"article_sha256":"216c2a686b663eb53d3d8cc33299c9dc54a70379941c0f5435868a527c0a91e7","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','128','4c8f8e7037efd5a789eb0055937ad5a2da7a0420c2db4d92473a6dbedeb5d7e6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:129','mayalex_normativos','10_LEYES_REGLAMENTOS','Por medio del contrato de aprendizaje un niño se obliga a trabajar para un patrono por un salario determinado a cambio de que el segundo le provea la formación técnica-profesional que requiera para aprender un oficio, arte o industria.','129','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":134,"article_sha256":"821e256aeba038fbc07decc3937c025be29b005de994584d6cc40cb95bb94c1a","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','129','b8d49d6d920abe7d0afffb4cf7fab069333f46f26d64971cf420611501f5fd63','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:130','mayalex_normativos','10_LEYES_REGLAMENTOS','La enseñanza se impartirá conforme a programas aprobados por el Instituto Nacional de Formación Profesional (INFOP). Este organismo, además, vigilará la forma en que se imparta la enseñanza y adoptará las medidas correctivas que considere adecuadas.

Lo dispuesto en este artículo será aplicable a la enseñanza que se imparta en los centros a que sea enviado un niño y en las escuelas de artes, oficios o industrias reconocidas por el Estado.','130','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":135,"article_sha256":"c1b20eea61377c9d72b27404517ff7d2bbf0a2699f0bf0b3051438348fd0cef8","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','130','357817dc3be5d56c761f88ae471731e444c1d8a8d4db3b0bcee4fcc5663c9ea9','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:131','mayalex_normativos','10_LEYES_REGLAMENTOS','La formación técnico-profesional a que hace referencia el artículo 130 anterior deberá:

a) Garantizar la asistencia del niño a una escuela de enseñanza básica obligatoria.

b) Asegurar que el niño contará con un horario especial para el aprendizaje.

c) Asegurar que la formación sea compatible con el desarrollo del niño; y, ch) Procurar la cobertura de la seguridad social.','131','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":136,"article_sha256":"a4c163fd6fdfaae172b9afa999795e826b666f2348dfe4d65312ce1406463a85","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','131','afe9ce42babde54cf8d33a10b1daa172bee0b6e1c844729b01cc605b81261b54','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:132','mayalex_normativos','10_LEYES_REGLAMENTOS','El Contrato de aprendizaje será siempre remunerado. La remuneración no podrá ser inferior al salario mínimo.

Si concluido el aprendizaje la relación laboral continua, el aprendiz adquirirá el carácter de trabajador y gozará de todos los derechos y prestaciones derivados de los contratos de trabajo, salvo que la Secretaría del Estado en los Despachos de Trabajo y Seguridad Social disponga otra cosa habida cuenta del desarrollo del niño, de su estado de salud o de la naturaleza de las labores que deba cumplir.

Para los efectos legales de los mencionados contratos, se entenderán iniciados desde que comenzó el aprendizaje.','132','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":137,"article_sha256":"134d0b217973e326d18d967964048fa209fd39cd517021699c025a17b3d46460","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','132','575b7d97da279780bfd0b0add5da93540a70ab0b8211efd78ecd6294b42ab75a','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:133','mayalex_normativos','10_LEYES_REGLAMENTOS','La Secretaría de Estado en los Despachos de Trabajo y Seguridad Social emitirá disposiciones reglamentarias sobre:

a) Las sanciones administrativas aplicables a las infracciones que se cometan durante el aprendizaje o la prestación de servicio por parte de los aprendices o trabajadores y los patronos.

b) La orientación que debe darse a los niños trabajadores, a sus padres o representantes legales y al patrono en relación con los derechos y deberes de aquellos, los horarios, permisos y prestaciones y las medidas sobre salud ocupacional; y, c) La forma en que se hará la inspección del trabajo de los niños y, en general, sobre los demás asuntos relacionados con su trabajo.','133','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":138,"article_sha256":"197ba03ea0e0adec4a79cf8b03b23e13577edd82c0096021c182b7c1ba788701","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','133','3bc10fb986144ce692b56a34bedad38905cc15d6d1c0d1f97fa2a718d20eb367','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:134','mayalex_normativos','10_LEYES_REGLAMENTOS','[DEROGADO — art. 11 del Decreto No. 35-2013]','134','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":139,"article_sha256":"ec58292777a8b59ce054af3859469165e4535c9c50cdf4ada0bdf79d97ea957d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"DEROGADO_INTEGRO","fuente_canonica":"D35_2013_ART_11","observaciones_canonicas":["Derogado íntegro (resolución del CLO 2026-11-18, PASAJES_134_141.md §6); el tipo pasa al art. 179-F del Código Penal (art. 8 del D.35-2013). A03 conservaba a)–c): no se adopta."]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','134','41aca8e8f4023d8844642c3da7b7623d352b51bafe506246c7ac29c141fdfa1d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:135','mayalex_normativos','10_LEYES_REGLAMENTOS','Será causa de emancipación judicial que el padre o la madre inciten u obliguen a un hijo dedicarse a la mendicidad o a realizar cualquiera de los actos a que se refieren los literales c) y ch) del artículo anterior.','135','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":140,"article_sha256":"0d5e10bc1e61bcdc8091bc679ddc8565df5ec631f15d7a4fddc5ab38f1975862","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','135','59b163907721eb922674bc86f9a4c0777a4ff2f133c95fd8be0020c5759cd8e3','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:136','mayalex_normativos','10_LEYES_REGLAMENTOS','Las corporaciones municipales y las organizaciones comunitarias y docentes cooperarán con la Secretaría de Estado en los Despachos de Trabajo y Seguridad Social en el cumplimiento de las obligaciones derivadas de este Código.','136','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":141,"article_sha256":"097649542077e10477c26586391cb41cd5aaf04a0f1d03eea761daca4698f9e1","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','136','e72feea6414ce2d1313d58553ae0707cd9ed2a5740a819061dae3fb8eab458b7','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:137','mayalex_normativos','10_LEYES_REGLAMENTOS','Las sanciones administrativas de las infracciones cometidas contra lo dispuesto en este capítulo serán aplicadas por la Secretaría de Estado en los Despachos de Trabajo y Seguridad Social. Tales sanciones no obstarán para que se deduzcan las responsabilidades civiles y penales que correspondan.','137','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":142,"article_sha256":"fe6d19ebede38f3b6ddc00b575fdb802ce1c540684da2e996dad1e482617a012","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','137','89d9f41e543f630501e68802b714739136d5acf59e0af5ddfe0ccf080cc2949d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:138','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Secretarías de Estado en los Despachos de Trabajo y Seguridad Social y de Salud, así como el Instituto Hondureño de la Niñez y la Familia, conjuntamente adoptarán las medidas que sean necesarias para que los niños cuyos padres o representantes legales trabajen puedan ser atendidos en guarderías infantiles mientras dura la jornada laboral.

Velarán, asimismo, porque dichas guarderías cuenten con las facilidades necesarias para que la permanencia sea provechosa para los niños en atención a su edad y estado físico y mental.

En todo caso, dichos servicios deberán estimular el desarrollo del niño, atender adecuadamente sus necesidades primarias de salud y nutrición y contribuir a su sostenido mejoramiento psico-social.

El personal que labore en los establecimientos de guarda de los niños deberá ser especialmente capacitado para cumplir sus funciones.','138','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":143,"article_sha256":"4f91819a6fc00fee19bdb6e3518342f5ab4709efd7d85024b6039403867dd879","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','138','1d3f084774219ea71b3bf6b9ca6362f86e82e0e9abf5af450af32125e9bcb6d5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:139','mayalex_normativos','10_LEYES_REGLAMENTOS','Un niño(a) es particularmente vulnerable al incumplimiento y a la violación de sus derechos, cuando se encuentra o se ve afectado(a) por situaciones, tales como:

a. Que se encuentre en estado de abandono; b. Carezca de atención suficiente para la satisfacción de sus necesidades básicas; c. Su patrimonio se encuentre amenazado por quienes lo administran; ch. Carezca de representante legal; d. Sea objeto de maltratos o de corrupción; e. Se encuentre en una situación especial que atente contra sus derechos o su integridad; y, f Sea adicto(a) a sustancias que produzcan dependencia o se encuentre expuesto a caer en la adicción.','139','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":144,"article_sha256":"511e4b6ad7849bf769d16626ef04dbd2b59f45d6596e5742243680ec42e748e1","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','139','cd7b218f2ad5abc34e7c349e6042be437fda013c91e53a4cd1a9038ff0fc38a8','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:140','mayalex_normativos','10_LEYES_REGLAMENTOS','Los niños y niñas cuyos derechos son vulnerados, quedan sujetos(as) a las medidas de protección consagradas en el presente Título.','140','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":145,"article_sha256":"e803e512ecf3b402eb10a289f7a40b67d56d4ce5709e45b3a53ebd876feeac41","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','140','3b5a686fcd1b9652777bfbd13509350f175b2926f7497911eb09ff5ac878a71c','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:141','mayalex_normativos','10_LEYES_REGLAMENTOS','Un niño o niña se encuentra en situación de abandono, cuando:

a) Fuere abandonado en lugares públicos; b) Falten en forma absoluta las personas que conforme a la Ley, tienen el cuidado personal de su crianza educación; y, c) No sea reclamado por sus padres o representantes legales al ser dado de alta, en establecimientos hospitalarios o de asistencia social.','141','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":146,"article_sha256":"3639d4570face98da5e7e57448061893344e2f8fd6c901f98a64d19c38395c46","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222","observaciones_canonicas":["Texto reformado (a–c); el art. 11 del D.35-2013 deroga los literales ch)–f) del 141 original (resolución del CLO 2026-11-18)."]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','141','0d0809b91d6dc010ebdcc9a68fd6f9bf753116c47531e658ba5cdd90b5b13514','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:142','mayalex_normativos','10_LEYES_REGLAMENTOS','Toda persona o institución que tenga conocimiento de la situación de abandono de un niño o niña, deberá denunciarlo al Instituto Hondureño de la Niñez y La Familia (IHNFA), Policía, Ministerio Público, Juzgados de Paz, Comisionados Municipales de Derechos Humanos, Defensorías de la Niñez y Mujer, para asegurar las medidas urgentes de protección e interponer la denuncia para el ejercicio de la acción penal.','142','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":147,"article_sha256":"d91c65861a5a1f061a4f310b0c81387a66d6cbf6f158ec3dbd74ebade3108654","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','142','87ecb3f3fdbcdcddbc5be8dbd011a1201fc2fc32342250ecb0c3ec68d1cf69de','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:143','mayalex_normativos','10_LEYES_REGLAMENTOS','Los(as) Directores(as) de los hospitales públicos y privados y de los demás Centros Asistenciales, están obligados a informar sobre los niños y niñas abandonados en sus dependencias y a entregarlos al Instituto Hondureño de la Niñez y la Familia (IHNFA), dentro de las veinticuatro (24) horas siguientes a la ocurrencia de hecho.','143','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":148,"article_sha256":"2f5e2f3089c9cfca34824858329e964eb505155d46332c1dc54e46f03ef8d95a","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','143','78defd2ccb79e1a0f39bc992c7287035fc09134f65cc761178a9ec9312805de1','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:144','mayalex_normativos','10_LEYES_REGLAMENTOS','Los centros a que se refiere el artículo precedente están obligados a dispensar de inmediato la atención de urgencia que requiera un niño. Ningún motivo podrá invocarse para negar dicha asistencia, ni siquiera la ausencia de representantes legales, la carencia de recursos económicos o la falta de cupo.','144','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":149,"article_sha256":"b1ab75bc169ad25e943adb7d29670d8e3c68dca8931130f30513e245423db8c6","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','144','19c901fb28398347b1d4d03ffab6002a88bbe4019b22e5d393b28c4b376d94f4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:145','mayalex_normativos','10_LEYES_REGLAMENTOS','Los(as) jefes de las misiones diplomáticas y consulares de Honduras que tengan conocimiento que un niño o niña hondureño(a) ha sido privado de su derecho a la familia o que ha sido internado en una institución pública o privada del país en el que estén acreditados, investigarán las causas de los hechos y le brindarán el auxilio legal y económico que necesite. El costo de este auxilio será reembolsado por el Estado de Honduras previa prueba.

De inmediato, informarán del hecho al Instituto Hondureño de la Niñez y La Familia (IHNFA), además le enviarán informe sobre los cambios que se hayan producido y en su caso el IHNFA realizará las gestiones necesarias a fin de lograr su repatriación.','145','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":150,"article_sha256":"b37e5c11659746963ad909f4e59559c179c8f219f7c68bef9a469a2d2d0f8ecf","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','145','a1ac02b7d796beea41527ac3b6d046c7412ce87cd7b59e91a4a824598266e3a1','A03_CODIGO_NINEZ_01',now())
